# ! [doc = " An encapsulation of `BufReader`'s buffer management logic."] # ! [doc = ""] # ! [doc = " This module factors out the basic functionality of `BufReader` in order to protect two core"] # ! [doc = " invariants:"] # ! [doc = " * `filled` bytes of `buf` are always initialized"] # ! [doc = " * `pos` is always <= `filled`"] # ! [doc = " Since this module encapsulates the buffer management logic, we can ensure that the range"] # ! [doc = " `pos..filled` is always a valid index into the initialized region of the buffer. This means"] # ! [doc = " that user code which wants to do reads from a `BufReader` via `buffer` + `consume` can do so"] # ! [doc = " without encountering any runtime bounds checks."] use split_decls_genesis :: ourprelude :: * ; use crate :: cmp ; use crate :: io :: { self , BorrowedBuf , ErrorKind , Read } ; use crate :: mem :: MaybeUninit ; pub struct Buffer { buf : Box < [MaybeUninit < u8 >] > , pos : usize , filled : usize , initialized : usize , } impl Buffer { #[inline] pub fn with_capacity (capacity : usize) -> Self { let buf = Box :: new_uninit_slice (capacity) ; Self { buf , pos : 0 , filled : 0 , initialized : 0 } } #[inline] pub fn try_with_capacity (capacity : usize) -> io :: Result < Self > { match Box :: try_new_uninit_slice (capacity) { Ok (buf) => Ok (Self { buf , pos : 0 , filled : 0 , initialized : 0 }) , Err (_) => { Err (io :: const_error ! (ErrorKind :: OutOfMemory , "failed to allocate read buffer")) } } } #[inline] pub fn buffer (& self) -> & [u8] { unsafe { self . buf . get_unchecked (self . pos .. self . filled) . assume_init_ref () } } #[inline] pub fn capacity (& self) -> usize { self . buf . len () } #[inline] pub fn filled (& self) -> usize { self . filled } #[inline] pub fn pos (& self) -> usize { self . pos } #[cfg (test)] pub fn initialized (& self) -> usize { self . initialized } #[inline] pub fn discard_buffer (& mut self) { self . pos = 0 ; self . filled = 0 ; } #[inline] pub fn consume (& mut self , amt : usize) { self . pos = cmp :: min (self . pos + amt , self . filled) ; } #[doc = " If there are `amt` bytes available in the buffer, pass a slice containing those bytes to"] #[doc = " `visitor` and return true. If there are not enough bytes available, return false."] #[inline] pub fn consume_with < V > (& mut self , amt : usize , mut visitor : V) -> bool where V : FnMut (& [u8]) , { if let Some (claimed) = self . buffer () . get (.. amt) { visitor (claimed) ; self . pos += amt ; true } else { false } } #[inline] pub fn unconsume (& mut self , amt : usize) { self . pos = self . pos . saturating_sub (amt) ; } #[doc = " Read more bytes into the buffer without discarding any of its contents"] pub fn read_more (& mut self , mut reader : impl Read) -> io :: Result < usize > { let mut buf = BorrowedBuf :: from (& mut self . buf [self . filled ..]) ; let old_init = self . initialized - self . filled ; unsafe { buf . set_init (old_init) ; } reader . read_buf (buf . unfilled ()) ? ; self . filled += buf . len () ; self . initialized += buf . init_len () - old_init ; Ok (buf . len ()) } #[doc = " Remove bytes that have already been read from the buffer."] pub fn backshift (& mut self) { self . buf . copy_within (self . pos .. self . filled , 0) ; self . filled -= self . pos ; self . pos = 0 ; } #[inline] pub fn fill_buf (& mut self , mut reader : impl Read) -> io :: Result < & [u8] > { if self . pos >= self . filled { debug_assert ! (self . pos == self . filled) ; let mut buf = BorrowedBuf :: from (& mut * self . buf) ; unsafe { buf . set_init (self . initialized) ; } let result = reader . read_buf (buf . unfilled ()) ; self . pos = 0 ; self . filled = buf . len () ; self . initialized = buf . init_len () ; result ? ; } Ok (self . buffer ()) } }